constexpr int N_OUTER = 3;  // Uranus, Neptune, Pluto (viewer kinds VIEW_PLANET + 5 .. + 7); the Blue Marble is blue_marble()
struct Outer {
  const uint8_t *data;
  size_t len;
  int w, h;
  const uint32_t *icon;
  const char *name, *credit;
};
inline Outer outer(int i) {
  static const char *const CR[N_OUTER] = {"NASA Voyager 2, 1986", "NASA Voyager 2, 1989", "NASA New Horizons, 2015"};
  switch (i) {
    case 0: return {OUTER_URANUS, 9994, 300, 300, OUTER_URANUS_ICON, "Uranus", CR[0]};
    case 1: return {OUTER_NEPTUNE, 12821, 300, 300, OUTER_NEPTUNE_ICON, "Neptune", CR[1]};
    case 2: return {OUTER_PLUTO, 23963, 300, 300, OUTER_PLUTO_ICON, "Pluto", CR[2]};
    default: return {nullptr, 0, 0, 0, nullptr, "", ""};
  }
}
inline Outer blue_marble() { return {OUTER_EARTH, sizeof(OUTER_EARTH), 300, 300, OUTER_EARTH_ICON, "Earth", "NASA Apollo 17, 1972"}; }
